#define PHONELM_PRECISION_LIBRARY
#include "upstream_precision_test.cpp"
#include <fstream>
namespace consistency {
using one::Vec;
// A separately written long-double Forward checks the double reference;
// neither mixed-precision matmul nor any Custom arithmetic is called here.
std::array<Vec,2> extended(const precision::Case& c,const Vec& wq,const Vec& wk){
 std::vector<long double> y(2048),q(2048),k(2048);for(unsigned r=0;r<32;++r){long double mean=0,var=0;for(unsigned j=0;j<64;++j)mean+=c.x[r*64+j];mean/=64;for(unsigned j=0;j<64;++j){long double t=(long double)c.x[r*64+j]-mean;var+=t*t;}long double inv=1/std::sqrt(var/64+(long double)1e-5f);for(unsigned j=0;j<64;++j)y[r*64+j]=((long double)c.x[r*64+j]-mean)*inv*c.gamma[j]+c.beta[j];}
 for(unsigned r=0;r<32;++r)for(unsigned j=0;j<64;++j){long double qs=0,ks=0;for(unsigned t=0;t<64;++t){qs+=y[r*64+t]*wq[t*64+j];ks+=y[r*64+t]*wk[t*64+j];}q[r*64+j]=qs;k[r*64+j]=ks;}
 std::array<Vec,2> p;for(unsigned h=0;h<2;++h){p[h].resize(1024);for(unsigned r=0;r<32;++r){long double logits[32],exp[32],mx=-1e300L,sum=0;for(unsigned j=0;j<32;++j){long double s=0;for(unsigned t=0;t<32;++t)s+=q[r*64+h*32+t]*k[j*64+h*32+t];logits[j]=s*(long double)probabilitycontract::scale()+(j>r?-10000.L:0.L);mx=std::max(mx,logits[j]);}for(unsigned j=0;j<32;++j){exp[j]=std::exp(logits[j]-mx);sum+=exp[j];}for(unsigned j=0;j<32;++j)p[h][r*32+j]=double(exp[j]/sum);}}return p;
}
void frozenHoldout(){std::ofstream f("synthetic-inputs.bin",std::ios::binary);if(!f)throw std::runtime_error("holdout output");auto put=[&](const auto& v){for(auto n:v){float x=float(n);f.write(reinterpret_cast<const char*>(&x),4);}};for(auto& z:precision::synthetic())for(auto key:{"layerinput","dy","gamma1","beta1","wq","wk"})put(z.v.at(key));for(auto& z:precision::syntheticGradients())for(auto& g:z){put(g.dp);put(g.dc);}if(!f)throw std::runtime_error("holdout write");}
int run(const char* fixture){frozenHoldout();auto fs=segmentstudy::lnCases(one::read(fixture));auto hs=precision::synthetic();fs.insert(fs.end(),hs.begin(),hs.end());double ref=0,baseline=0,local=0;unsigned complete=0,words=0;
 // Verify new baseline equations against the unchanged independent one:: FP32
 // implementation over every Forward fixture and synthetic case.
 for(auto& z:fs){auto c=one::lncase(z);c.x=z.v.at("layerinput");c.gamma=z.v.at("gamma1");c.beta=z.v.at("beta1");auto wq=one::d(z.v.at("wq")),wk=one::d(z.v.at("wk"));auto p=precision::ideal(c,wq,wk),ld=extended(c,wq,wk);auto f=precision::forward(c,wq,wk,precision::candidates()[0]);auto ln=mmfixture::ln::anchoredFp32Oracle(c,64);auto q=one::mm(one::d(ln.y),wq,32,64,64,false,false,true),k=one::mm(one::d(ln.y),wk,32,64,64,false,false,true);for(unsigned h=0;h<2;++h){ref=std::max(ref,attribution::distance(p[h],ld[h]));auto raw=one::mm(one::split(q,h),one::split(k,h),32,32,32,false,true,true);auto pf=one::softmax(probabilitycontract::masked(one::mul(raw,{double(probabilitycontract::scale())},true),true),true);baseline=std::max(baseline,attribution::distance(pf,f.p[h]));for(unsigned i=0;i<1024;++i)words+=forwardsoftmaxreference::bits(float(pf[i]))!=forwardsoftmaxreference::bits(float(f.p[h][i]));auto received=one::mm(one::split(q,h),one::split(k,h),32,32,32,false,true);auto test=precision::matmul(one::split(q,h),one::split(k,h),32,32,32,true,2);local=std::max(local,attribution::distance(test,precision::stored(received)));++complete;}}
 if(ref>1e-10||baseline!=0||words||local!=0||complete!=120)throw std::runtime_error("independent reference/FP32 baseline agreement");
 std::cout<<"{\"kind\":\"reference_checks\",\"heads\":"<<complete<<",\"double_long_double_p_error\":"<<ref<<",\"baseline_value_error\":"<<baseline<<",\"baseline_word_mismatches\":"<<words<<",\"same_operand_double_output_error\":"<<local<<",\"holdout_written\":true}\n";
 auto original=one::read(fixture);auto gs=upstreamreference::fullUpstream(original);std::vector<std::array<precision::Gradient,2>> gr;for(auto& z:gs){auto a=one::reference(z,true);std::array<precision::Gradient,2> g;for(unsigned h=0;h<2;++h){auto prefix="h"+std::to_string(h)+"_";g[h]={a.at(prefix+"dp"),a.at(prefix+"dc")};}gr.push_back(g);}
 for(auto& a:precision::candidates())if(a.id=="C7"||a.id=="B2"||a.id=="B4"){double rep=0,arithmetic=0,total=0;unsigned pairs=0;for(unsigned fi=0;fi<44;++fi){auto& z=fs[fi];auto c=one::lncase(z);c.x=z.v.at("layerinput");c.gamma=z.v.at("gamma1");c.beta=z.v.at("beta1");auto f=precision::forward(c,one::d(z.v.at("wq")),one::d(z.v.at("wk")),a);for(unsigned h=0;h<2;++h)for(auto& g:gr){auto ds=probabilitycontract::backward(g[h].dp,f.p[h]);for(bool key:{false,true}){auto state=one::split(key?f.q:f.k,h);auto exact=one::mul(one::mm(ds,state,32,32,32,key,false),{double(probabilitycontract::scale())});auto roundedState=precision::stored(state);auto representation=one::mul(one::mm(ds,roundedState,32,32,32,key,false),{double(probabilitycontract::scale())});auto fp=one::mul(one::mm(precision::stored(ds),roundedState,32,32,32,key,false,true),{double(probabilitycontract::scale())},true);rep=std::max(rep,attribution::distance(exact,representation));arithmetic=std::max(arithmetic,attribution::distance(representation,fp));total=std::max(total,attribution::distance(exact,fp));}++pairs;}}
 std::cout<<"{\"kind\":\"qk_backward_consistency\",\"candidate\":\""<<a.id<<"\",\"pairs\":"<<pairs<<",\"saved_qk_representation_error\":"<<rep<<",\"fp32_arithmetic_error\":"<<arithmetic<<",\"total_local_gradient_error\":"<<total<<",\"same_forward_backward_operand_values\":"<<(rep==0?"true":"false")<<",\"gradient_gate\":"<<(total<=.01?"true":"false")<<",\"training_ready\":false}\n";}
 return 0;}
}
int main(int argc,char** argv){std::cout<<std::setprecision(17);try{if(argc!=2)return 1;return consistency::run(argv[1]);}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 4;}}
